"""Read-only independent paper-baseline review. No project imports or inference.
Reproduce: cd /home/lucky/devdir/rgzndl && PYTHONDONTWRITEBYTECODE=1 .venv/bin/python /tmp/ect_paper_results_independent_review.py
Only /tmp output is written. Test files are hashed as bytes, never loaded as arrays.
"""
from pathlib import Path
from datetime import datetime, timezone
import csv, gzip, hashlib, json, math, os, sys
import numpy as np
import torch
ROOT = Path('/home/lucky/devdir/rgzndl')
BASE = ROOT / 'results/experiments/paper_baseline_v1'
OUT = Path('/tmp/ect_paper_results_independent_review.json')
TOL = 1e-12
inputs = {}
checks = []
findings = []
max_metric_error = 0.0
max_summary_error = 0.0

def sha(path, refresh=False):
    path = Path(path)
    if not path.is_absolute(): path = ROOT / path
    key = str(path)
    if refresh or key not in inputs:
        h = hashlib.sha256()
        with path.open('rb') as f:
            for block in iter(lambda: f.read(2**20), b''): h.update(block)
        digest = h.hexdigest()
        if not refresh: inputs[key] = digest
        return digest
    return inputs[key]

def read(path):
    path = Path(path)
    if not path.is_absolute(): path = ROOT / path
    sha(path)
    return json.loads(path.read_text())

def check(ok, label, details=None, priority='P1'):
    row = {'check': label, 'passed': bool(ok)}
    if details is not None: row['details'] = details
    checks.append(row)
    if not ok:
        findings.append({'priority': priority, 'title': label, 'evidence': details,
                         'reproduction': 'Run the embedded review script; inspect checks with passed=false.'})

def same(a, b, label):
    check(a == b, label, None if a == b else {'actual': a, 'expected': b})

def hash_table(table, prefix=ROOT, label='hash'):
    for name, expected in table.items():
        path = Path(name)
        if not path.is_absolute(): path = prefix / path
        check(path.is_file(), f'{label}: exists {path}')
        if path.is_file(): same(sha(path), expected, f'{label}: SHA {path}')

def text_hash(obj, key, digest_key, label):
    same(hashlib.sha256(obj[key].encode()).hexdigest(), obj[digest_key], label)

def canonical(obj):
    return hashlib.sha256(json.dumps(obj, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode()).hexdigest()

def metrics(y, p):
    cm = np.bincount(20*y+p, minlength=400).reshape(20,20)
    true_counts = cm.sum(axis=1)
    predicted_counts = cm.sum(axis=0)
    tp = cm.diagonal()
    precision = np.divide(tp,predicted_counts,out=np.zeros(20),where=predicted_counts>0)
    recall = np.divide(tp,true_counts,out=np.zeros(20),where=true_counts>0)
    f1 = np.divide(2*tp,true_counts+predicted_counts,out=np.zeros(20),where=true_counts+predicted_counts>0)
    return {'accuracy': float(tp.sum()/len(y)), 'macro_f1': float(f1.mean()),
            'confusion_matrix':cm.tolist(), 'per_class':{
                str(c):{'precision':float(precision[c]),'recall':float(recall[c]),
                        'f1-score':float(f1[c]), 'support':int(true_counts[c])} for c in range(20)}}

def compare_metrics(actual, recorded, label):
    global max_metric_error
    same(set(actual),set(recorded),label+' metric schema')
    same(actual['confusion_matrix'],recorded['confusion_matrix'],label+' confusion matrix')
    same(set(actual['per_class']),set(recorded['per_class']),label+' string class keys')
    error = max(abs(actual[k]-recorded[k]) for k in ['accuracy','macro_f1'])
    for c in actual['per_class']:
        for k,v in actual['per_class'][c].items():
            error = max(error,abs(v-recorded['per_class'][c][k]))
    max_metric_error = max(max_metric_error,error)
    check(error<=TOL,label+' independent metric formulas',{'maximum_absolute_error':error,'tolerance':TOL})

def stats(values):
    a=np.asarray(values,dtype=np.float64)
    return {'values':a.tolist(),'mean':float(a.mean()),'sample_sd':float(a.std(ddof=1)),
            'min':float(a.min()),'max':float(a.max()),'n_training_seeds':len(a)}

def date(s): return datetime.fromisoformat(s)

def compare_scalar(actual, recorded, label, tolerance=TOL):
    global max_summary_error
    error=abs(float(actual)-float(recorded))
    if tolerance==TOL: max_summary_error=max(max_summary_error,error)
    check(error<=tolerance,label,{'actual':actual,'recorded':recorded,'absolute_error':error,'tolerance':tolerance})

def compare_tree(actual, recorded, label, tolerance=TOL):
    if isinstance(actual,dict):
        same(set(actual),set(recorded),label+' keys')
        for k,v in actual.items():
            if k in recorded: compare_tree(v,recorded[k],label+'/'+str(k),tolerance)
    elif isinstance(actual,list):
        same(len(actual),len(recorded),label+' length')
        for i,(a,b) in enumerate(zip(actual,recorded)): compare_tree(a,b,label+'/'+str(i),tolerance)
    elif isinstance(actual,(int,float)) and not isinstance(actual,bool):
        compare_scalar(actual,recorded,label,tolerance)
    else: same(actual,recorded,label)

def crosscheck_summary(summary_path,runs,aggregate,durations,comparisons,old_clean,registry):
    summary=read(summary_path)
    prefix=summary_path.parent
    text_hash(summary,'analysis_script_text','analysis_script_sha256','main summary script full text SHA')
    hash_table(summary['input_files_sha256'],label='main summary input')
    hash_table(summary['output_files_sha256'],prefix=prefix,label='main summary output')
    same(summary['heldout_test_evaluated'],False,'main summary no test inference')
    same(summary['verified_predictions'],81600,'main summary full prediction count')
    compare_scalar(max_metric_error,summary['maximum_independent_metric_error'],'main summary metric error')
    same([s['seed'] for s in summary['seeds']],[0,1,2],'main summary all seeds retained')
    expected_binding=dict(registry['files_sha256']|registry['code_sha256'])
    expected_inputs={str((BASE/'registry.json').relative_to(ROOT)):sha(BASE/'registry.json')}
    for r in runs:
        folder=BASE/r['run_id'];report=read(folder/'report.json');proof=read(BASE/'verification'/f"{r['run_id']}_cuda.json")
        for name,h in report['files_sha256'].items():expected_binding[str((folder/name).relative_to(ROOT))]=h
        for name,h in proof['files_sha256'].items():
            p=Path(name);key=str(p.relative_to(ROOT)) if p.is_absolute() else name
            if key in expected_binding: same(expected_binding[key],h,'main binding union repeated hash '+key)
            expected_binding[key]=h
        for p in [folder/'report.json',BASE/'verification'/f"{r['run_id']}_cuda.json"]: expected_inputs[str(p.relative_to(ROOT))]=sha(p)
    for p in [ROOT/'results/experiments/formal_v1/training_summary.json',BASE/'analysis_plan_v1/plan.json']:expected_inputs[str(p.relative_to(ROOT))]=sha(p)
    same(summary['input_files_sha256'],expected_inputs,'main summary full declared input hash table')
    same(summary['verified_binding_files_count'],len(expected_binding),'main summary bound file count independently reconstructed')
    hash_table(expected_binding,label='main summary complete binding union')
    for split in ['train','validation']:
        for k in ['accuracy','macro_f1']:
            expected={f:aggregate[split][k][f] for f in ['mean','sample_sd','min','max']};expected['n']=3
            compare_tree(expected,summary['aggregate'][split][k],'main summary '+split+'/'+k)
    compare_scalar(aggregate['validation']['accuracy']['mean'],0.723125,'user expected validation Accuracy mean')
    compare_scalar(aggregate['validation']['accuracy']['sample_sd'],0.08777412417677546,'user expected sample SD ddof=1')
    compare_scalar(comparisons['svm']['accuracy_difference_percentage_points'],11.40625,'user expected SVM difference pp')
    for family,comparison in comparisons.items():
        expected_reference=old_clean[family] if family=='svm' else {k:old_clean[family][k]['mean'] for k in ['accuracy','macro_f1']}
        compare_tree(expected_reference,summary['comparisons'][family]['reference'],'main reference '+family)
        for k,v in comparison.items():compare_scalar(v,summary['comparisons'][family][k],'main clean comparison '+family+'/'+k)
    for r,s in zip(runs,summary['seeds']):
        label='main seed '+str(r['seed'])
        same(s['selected_epoch'],r['selected_epoch'],label+' selected epoch')
        for split in ['train','validation']:
            compare_tree({k:r['metrics'][split][k] for k in ['accuracy','macro_f1']},s[split],label+' '+split+' CSV metrics')
            compare_tree({g:{k:m[k] for k in ['accuracy','macro_f1']} for g,m in r['group_metrics'][split].items()},s['group_metrics'][split],label+' '+split+' group CSV metrics')
        compare_tree(r['train_minus_validation'],s['eval_train_minus_validation'],label+' same inference condition gap')
        same(r['zero_recall_validation_classes'],s['zero_validation_recall_classes'],label+' zero recall classes')
        es=read(BASE/r['run_id']/'report.json')['epochs'];v=[e['validation']['accuracy'] for e in es if e['validation'] is not None]
        expected_trend={'train_loss_first100':r['windows']['train_loss']['epochs_1_100_mean'],
             'train_loss_last100':r['windows']['train_loss']['epochs_901_1000_mean'],
             'online_train_accuracy_first100':r['windows']['online_train_accuracy']['epochs_1_100_mean'],
             'online_train_accuracy_last100':r['windows']['online_train_accuracy']['epochs_901_1000_mean'],
             'validation_first10':r['windows']['validation_accuracy']['first_10_mean'],
             'validation_last10':r['windows']['validation_accuracy']['last_10_mean'],
             'validation_last10_range':[float(np.min(v[-10:])),float(np.max(v[-10:]))],
             'validation_checkpoints':r['windows']['validation_at_epochs']}
        compare_tree(expected_trend,s['trends'],label+' fixed analysis windows')
        for field,key in [('training_and_evaluation_seconds','report_seconds'),('cuda_verification_seconds','proof_seconds'),('epoch_time_total_seconds','epoch_sum_seconds')]:
            compare_scalar(r['duration'][key],s[field],label+' '+field,1e-8)
    compare_scalar(durations['sum_training_report_seconds'],summary['sum_training_and_evaluation_seconds'],'main sum report time',1e-8)
    compare_scalar(durations['orchestration_wall_seconds'],summary['chain_elapsed_seconds'],'main total chain wall time',1e-8)
    plan=read(BASE/'analysis_plan_v1/plan.json')
    same(plan['training_registry_sha256'],sha(BASE/'registry.json'),'analysis plan registry anchor')
    same(plan['timing'],'supplement_after_training_start_and_after_early_validation_seen','analysis timing honest historical state')
    same(plan['selection_changed'],False,'analysis plan unchanged model selection')
    same(plan['test_inference_allowed'],False,'analysis plan no test inference')
    hash_table(plan['snapshot_sha256'],prefix=BASE/'analysis_plan_v1',label='analysis recording snapshots')
    text_hash(plan,'recording_script_text','recording_script_sha256','analysis recording script full text SHA')
    same([q['id'] for q in plan['questions']],['Q1','Q2','Q3','Q4','Q5'],'five fixed analysis questions')
    expected_files={'epoch_metrics.csv','group_metrics.csv','seed_metrics.csv','per_class.csv',
                    *[f'figures/{n}.{ext}' for n in ['validation_confusion','group_and_eval_diagnostics','learning_curves'] for ext in ['png','svg']]}
    same(set(summary['output_files_sha256']),expected_files,'main all 10 output identities')
    actual_files={str(p.relative_to(prefix)) for p in prefix.rglob('*') if p.is_file() and p.name!='summary.json'}
    same(actual_files,expected_files,'main directory matches declared complete outputs')
    def csv_file(name):
        p=prefix/name;sha(p)
        with p.open(newline='') as f:return list(csv.DictReader(f))
    def compare_csv(actual,expected,label,keys,tolerance=TOL):
        # Compare keyed records, requiring complete unique identities; order may follow producer dict order.
        a={tuple(r[k] for k in keys):r for r in actual};b={tuple(str(r[k]) for k in keys):r for r in expected}
        same(len(a),len(actual),label+' no duplicate identities');same(set(a),set(b),label+' complete row keys')
        worst=0.0;bad=[]
        for key,e in b.items():
            if key not in a:continue
            row=a[key]
            if set(row)!=set(e):bad.append({'key':key,'reason':'schema'});continue
            for field,value in e.items():
                if field in keys:
                    if row[field]!=str(value):bad.append({'key':key,'field':field})
                elif value is None:
                    if row[field]!='':bad.append({'key':key,'field':field,'reason':'non-validation value must be empty'})
                else:
                    error=abs(float(row[field])-float(value));worst=max(worst,error)
                    if error>tolerance:bad.append({'key':key,'field':field,'actual':row[field],'expected':value,'error':error})
        check(not bad,label+' independent content recomputation',{'rows':len(actual),'max_absolute_error':worst,'bad_count':len(bad),'first_differences':bad[:10]})
        return {'row_count':len(actual),'maximum_absolute_error':worst}
    expected_epochs=[];expected_groups=[];expected_classes=[];expected_seeds=[]
    for r in runs:
        seed=r['seed'];es=read(BASE/r['run_id']/'report.json')['epochs']
        for e in es:
            expected_epochs.append({'seed':seed,'epoch':e['epoch'],'loss':e['train_loss'],'online_train_accuracy':e['online_train_accuracy'],
                'validation_accuracy':None if e['validation'] is None else e['validation']['accuracy'],
                'validation_macro_f1':None if e['validation'] is None else e['validation']['macro_f1'],'epoch_seconds':e['elapsed_seconds']})
        for split in ['train','validation']:
            for group,m in r['group_metrics'][split].items():expected_groups.append({'seed':seed,'split':split,'group_id':group,'accuracy':m['accuracy'],'macro_f1':m['macro_f1']})
            for c,m in r['metrics'][split]['per_class'].items():expected_classes.append({'seed':seed,'split':split,'class_index':c,**m})
        expected_seeds.append({'seed':seed,'selected_epoch':r['selected_epoch'],'train_accuracy':r['metrics']['train']['accuracy'],
            'validation_accuracy':r['metrics']['validation']['accuracy'],'validation_macro_f1':r['metrics']['validation']['macro_f1'],'elapsed_seconds':r['duration']['report_seconds']})
    csv_checks={}
    for name,expected,keys,tolerance in [('epoch_metrics.csv',expected_epochs,['seed','epoch'],1e-8),
            ('group_metrics.csv',expected_groups,['seed','split','group_id'],TOL),
            ('per_class.csv',expected_classes,['seed','split','class_index'],TOL),('seed_metrics.csv',expected_seeds,['seed'],1e-8)]:
        csv_checks[name]=compare_csv(csv_file(name),expected,'main output '+name,keys,tolerance)
    # Verify static drawing program only reads completed artifacts; do not execute its publishing code.
    import ast
    tree=ast.parse(summary['analysis_script_text'])
    imports=[]
    for node in ast.walk(tree):
        if isinstance(node,ast.Import):imports.extend(x.name for x in node.names)
        elif isinstance(node,ast.ImportFrom):imports.append(node.module or '')
    check(not any(x.startswith(('torch','src','ect')) for x in imports),'main drawing script has no model/project inference imports',{'imports':sorted(set(imports))})
    log_path=Path('/tmp/ect_paper_results_regression.log');log_sha=sha(log_path);log=log_path.read_text()
    import re
    match=re.search(r'Ran (\d+) tests in ([\d.]+)s\s*\n\s*OK\s*$',log)
    check(bool(match) and int(match.group(1))==264,'provided completed regression log 264 tests exit result OK')
    check('FAILED' not in log and not re.search(r'\bskipped\b',log),'provided regression log no failures/skips')
    # User reports process exit0. We verify the log, not claim that we reran regression.
    regression={'path':str(log_path),'sha256':log_sha,'test_count':int(match.group(1)) if match else None,
        'elapsed_seconds':float(match.group(2)) if match else None,'log_result':'OK' if match else 'unverified',
        'execution':'Existing mainline regression log inspected; no tests rerun by this review.',
        'reported_process_exit_code':0,'exit_code_source':'user report, log does not independently encode process exit code'}
    return {'path':str(summary_path),'status':'compared','comparison_performed':True,'sha256':sha(summary_path),
        'analysis_script_sha256':summary['analysis_script_sha256'],'input_files_sha256':summary['input_files_sha256'],
        'output_files_sha256':summary['output_files_sha256'],'complete_bound_file_count':len(expected_binding),
        'maximum_numeric_metric_difference':max_summary_error,'csv_content_checks':csv_checks,
        'fixed_window_macro_f1_and_differences':'Independently computed in this review windows; mainline trends record Accuracy windows and selected checkpoint Accuracy/Macro-F1.',
        'group_and_class_statistics':'Mainline exports all per-seed group/class rows; independent ddof=1 group/class statistics are included in this review.',
        'regression_log_review':regression}

def main():
    registry=read(BASE/'registry.json')
    same(sha(BASE/'registry.json'),'791e85504ff55f91d829ed94464e81ae53789186a0879aa27c188c7b14cc77c4','frozen registry anchor')
    same(len(registry['code_sha256']),13,'complete 13 registered sources')
    hash_table(registry['code_sha256'],label='registry source')
    hash_table(registry['files_sha256'],label='registry bound input/acceptance/data')
    for stem in ['base_config','design','acceptance']:
        same(sha(registry[stem+'_path']),registry[stem+'_sha256'],stem+' SHA anchor')
    acceptance=read(registry['acceptance_path'])
    same(acceptance['code_sha256'],registry['code_sha256'],'acceptance 13-source identity')
    same(acceptance['status'],'verified','runner acceptance status')
    check(all(v is True for v in acceptance['checks'].values()),'runner acceptance checks')
    hash_table(acceptance['files_sha256'],label='acceptance file')
    text_hash(acceptance['execution_script'],'text','sha256','acceptance script full text SHA')
    regression=read(Path(registry['acceptance_path']).parent/'regression.json')
    same(regression['test_count'],264,'frozen regression count')
    same(regression['skipped'],0,'frozen regression skipped')
    same(regression['status'],'passed','frozen regression status')
    same(regression['code_sha256'],registry['code_sha256'],'regression source binding')
    for info in acceptance['runs']:
        ap=read(info['verification_path']); ar=read(Path(info['run_dir'])/'report.json')
        same(ap['status'],'verified','acceptance '+info['device']+' proof status')
        same(ap['device'],info['device'],'acceptance proof device')
        same(ap['prediction_counts'],{'train':40,'validation':40},'acceptance 40/40 proof counts')
        same(ap['report_sha256'],sha(Path(info['run_dir'])/'report.json'),'acceptance report-proof SHA')
        same(ar['sample_counts'],ap['prediction_counts'],'acceptance report counts')
        check(ar['parameter_update_l2']>0,'acceptance actual learning update')
        hash_table(ap['files_sha256'],label='acceptance proof evidence')
        text_hash(ap['script'],'text','sha256','acceptance proof embedded script SHA')
    transfer=read(acceptance['cpu_transfer_verification_path'])
    same(transfer['device'],'cpu','acceptance CUDA weights CPU transfer device')
    same(transfer['status'],'verified','acceptance CPU transfer verified')
    same(transfer['prediction_counts'],{'train':40,'validation':40},'acceptance CPU transfer 80 predictions')
    hash_table(transfer['files_sha256'],label='CPU transfer evidence')
    text_hash(transfer['script'],'text','sha256','CPU transfer script SHA')
    design=read(registry['design_path'])
    same(design['training_runner_implemented'],False,'historical design implementation false preserved')
    same(design['execution_registry_bound'],False,'historical design registry false preserved')
    metadata=read('data/processed/grouped_v1/metadata.json')
    data_summary=read(metadata['summary_path'])
    norm=read('data/processed/grouped_v1/normalization.json')
    identity={'cache_dir':'data/processed/grouped_v1','cache_metadata_sha256':sha('data/processed/grouped_v1/metadata.json'),
              'cache_files_sha256':metadata['files_sha256'],'manifest_sha256':metadata['manifest_sha256'],
              'summary_path':metadata['summary_path'],'summary_sha256':metadata['summary_sha256'],
              'raw_inputs':metadata['inputs'],'sample_counts':metadata['sample_counts'],
              'normalization_sha256':sha('data/processed/grouped_v1/normalization.json')}
    same(identity,registry['data_identity'],'registered full data identity')
    same(metadata['manifest_sha256'],data_summary['manifest_sha256'],'metadata/manifest summary SHA table')
    same(norm['fitted_split'],'train','normalization trained only on train')
    same(norm['ddof'],0,'normalization ddof=0')
    same(norm['count_per_channel'],24000*250,'normalization sample count')
    records={}
    for split,n in [('train',24000),('validation',3200)]:
        mpath=ROOT/Path(metadata['summary_path']).parent/f'{split}.jsonl'
        sha(mpath)
        records[split]=[json.loads(line) for line in mpath.read_text().splitlines()]
        same(len(records[split]),n,split+' manifest count')
        yy=np.load(ROOT/f'data/processed/grouped_v1/{split}_y.npy',allow_pickle=False)
        same(yy.tolist(),[r['class_index'] for r in records[split]],split+' cached labels/manifest order')
        xx=np.load(ROOT/f'data/processed/grouped_v1/{split}_x.npy',allow_pickle=False,mmap_mode='r')
        same(xx.shape,(n,250,2),split+' cache shape')
        same(str(xx.dtype),'float32',split+' cache dtype')
        check(bool(np.isfinite(xx).all()),split+' cache finite')
        xx._mmap.close()
    check(not ({r['wave_sha256'] for r in records['train']} & {r['wave_sha256'] for r in records['validation']}),'train/validation wave identity disjoint')
    check(not ({r['group_id'] for r in records['train']} & {r['group_id'] for r in records['validation']}),'train/validation connected groups disjoint')
    status=read(BASE/'execution_status.json')
    same(status['registry_sha256'],sha(BASE/'registry.json'),'execution status registry SHA')
    text_hash(status,'orchestration_script_text','orchestration_script_sha256','orchestration script full text SHA')
    same(status['heldout_test_evaluated'],False,'status no heldout test')
    same([r['seed'] for r in registry['runs']],[0,1,2],'three seeds retained')
    runs=[]
    for run in registry['runs']:
        rid=run['run_id']; folder=ROOT/run['output_dir']; label=rid+': '
        report=read(folder/'report.json'); config=read(run['config_path']); proof_path=BASE/'verification'/f'{rid}_cuda.json'
        proof=read(proof_path); sr=next(x for x in status['runs'] if x['run_id']==rid)
        hash_table(sr['logs_sha256'],label=label+'logs')
        same(sr['status'],'complete_verified',label+'execution status')
        same(sr['report_sha256'],sha(folder/'report.json'),label+'execution report SHA')
        same(sr['verification_sha256'],sha(proof_path),label+'execution proof SHA')
        same(report['status'],'complete',label+'complete report')
        check(not (folder/'failure.json').exists() and not (folder/'running.marker').exists(),label+'no failed/incomplete marker')
        same(report['config'],config,label+'report and file config')
        same(canonical(config),run['resolved_config_sha256'],label+'canonical config SHA')
        same(report['config_sha256'],canonical(config),label+'report config SHA')
        same(sha(run['config_path']),run['config_file_sha256'],label+'file config SHA')
        fixed={'max_epochs':1000,'validation_every_epochs':10,'selection':['validation_accuracy','earlier_epoch'],
               'patience':None,'seed':run['seed'],'learning_rate':4e-5,'learning_rate_milestones_epochs':[5000,7500],
               'learning_rate_values':[4e-6,4e-7],'optimizer':'Adam','batch_size':128,'crop_length':224,
               'validation_crops':10,'validation_crop_seed':10,'train_per_class':None,'validation_per_class':None,
               'test_classification_enabled':False,'deterministic':True,'tf32':False}
        for k,v in fixed.items(): same(config[k],v,label+'fixed config '+k)
        expected_registration={'registry_path':str((BASE/'registry.json').relative_to(ROOT)),
             'registry_sha256':sha(BASE/'registry.json'),'protocol':registry['protocol'],'registered_utc':registry['registered_utc'],
             'acceptance_sha256':registry['acceptance_sha256'],**{k:run[k] for k in ['run_id','seed','config_path','config_file_sha256','resolved_config_sha256','output_dir']}}
        same(report['execution_registration'],expected_registration,label+'report registration chain')
        same(proof['execution_registration'],expected_registration,label+'proof registration chain')
        for obj in [report,proof]:
            same(obj['cache_metadata_sha256'],identity['cache_metadata_sha256'],label+'metadata binding')
            same(obj['normalization_sha256'],identity['normalization_sha256'],label+'normalization binding')
